-- Check records below average efficiency
SELECT COUNT(*) FROM maintenance 
WHERE revlossusd / NULLIF((maintcostusd + cleancostusd + replacecostusd), 0) < 0.43830755684088688019;

-- Try deleting records with cost efficiency <= average
DELETE FROM maintenance 
WHERE revlossusd / NULLIF((maintcostusd + cleancostusd + replacecostusd), 0) <= (
    SELECT AVG(revlossusd / NULLIF((maintcostusd + cleancostusd + replacecostusd), 0)) 
    FROM maintenance
);

-- Verify: how many records have cost efficiency <= average
