-- Maybe poor cost efficiency means total costs > revenue loss (ratio < 1)
SELECT COUNT(*) FROM maintenance 
WHERE (maintcostusd + cleancostusd + replacecostusd) > revlossusd;

-- Maybe poor = high maintenance costs (above average total cost)
SELECT COUNT(*) FROM maintenance 
WHERE (maintcostusd + cleancostusd + replacecostusd) > (
    SELECT AVG(maintcostusd + cleancostusd + replacecostusd) FROM maintenance
);

